        Assertions.fail(exp.getMessage());
        return null;
    });
    f.get(10, TimeUnit.SECONDS);
    MeasureQuery query = new MeasureQuery(Lists.newArrayList(groupName), "testMetric_minute", new TimestampRange(begin.toEpochMilli(), now.plus(1, ChronoUnit.MINUTES).toEpochMilli()), ImmutableSet.of("service_id", "tag"), ImmutableSet.of("value"));
    await().atMost(10, TimeUnit.SECONDS).untilAsserted(() -> {
